return-response.set-body:
@{
                return new JObject(
                    new JProperty("subscription", context.Subscription.Id),
                    new JProperty("product", context.Product == null ? null : context.Product.Id),
                    new JProperty("startDate", context.Subscription.StartDate.HasValue ? context.Subscription.StartDate.Value.ToString("o") : null),
                    new JProperty("endDate", context.Subscription.EndDate.HasValue ? context.Subscription.EndDate.Value.ToString("o") : null),
                    new JProperty("utcNow", DateTime.UtcNow.ToString("o"))).ToString();
            }
